// Developer: gengyun
// Purpose: Prototype recipe editor.

import SwiftUI
struct RecipeEditorView:View{
 @Environment(AppStore.self)private var store;@Environment(\.dismiss)private var dismiss;@State var recipe:Recipe;@State private var ingredient="";@State private var step=""
 var body:some View{Form{Section("Recipe"){TextField("Title",text:$recipe.title);Stepper("Servings: \(recipe.servings)",value:$recipe.servings,in:1...24);Stepper("Minutes: \(recipe.minutes)",value:$recipe.minutes,in:0...600,step:5)};Section("Ingredients"){ForEach(recipe.ingredients){x in Text("\(x.name)  \(x.amount)")};TextField("e.g. Tomatoes — 3",text:$ingredient);Button("Add ingredient"){let p=ingredient.split(separator:"—",maxSplits:1).map{$0.trimmingCharacters(in:.whitespaces)};guard !p.isEmpty,!p[0].isEmpty else{return};recipe.ingredients.append(Ingredient(name:p[0],amount:p.count>1 ? p[1]:""));ingredient=""}};Section("Steps"){ForEach(recipe.steps){Text($0.text)};TextField("Add a step",text:$step,axis:.vertical);Button("Add step"){let v=step.trimmingCharacters(in:.whitespacesAndNewlines);guard !v.isEmpty else{return};recipe.steps.append(RecipeStep(text:v));step=""}}}.navigationTitle("Edit Recipe").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Save"){let pending=step.trimmingCharacters(in:.whitespacesAndNewlines);if !pending.isEmpty{recipe.steps.append(RecipeStep(text:pending))};recipe.needsReview=recipe.ingredients.isEmpty||recipe.steps.isEmpty;store.upsert(recipe);dismiss()}.disabled(recipe.title.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty)}}}
}
